17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Optional;
23	import java.util.concurrent.atomic.AtomicLong;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import tools.jackson.databind.ObjectMapper;
28	import tools.jackson.databind.json.JsonMapper;
29	import org.springframework.http.HttpHeaders;
30	import org.springframework.http.HttpStatus;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.service.IdempotencyStore;
47	import org.springframework.samples.petclinic.util.BusinessDays;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.servlet.http.HttpServletRequest;
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger: on a successful create an audit line records the owner id,
67	     * memberId and registrationDate. */
68	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
69	
70	    /** Dedicated notification logger: on a successful create a welcome notification is enqueued,
71	     * recording the owner id and memberId. */
72	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
73	
74	    /** Serializes the structured {@link OwnerCreatedEvent} emitted on each create. */
75	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
76	
77	    /** Monotonically increasing sequence number assigned to each successful create's audit event. */
78	    private static final AtomicLong AUDIT_EVENT_SEQ = new AtomicLong();
79	
80	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
81	    private static final int CITY_CAPACITY = 50;
82	
83	    /** Once a city already holds at least this many owners (but fewer than {@link #CITY_CAPACITY}),
84	     * a new owner created for that city is flagged with {@code capacityWarning} to signal the city
85	     * is approaching its capacity limit. */
86	    private static final int CITY_CAPACITY_WARNING_THRESHOLD = 40;
87	
88	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
89	     * create is rejected once this many owners already carry today's registration date. */
90	    private static final int DAILY_REGISTRATION_LIMIT = 100;
91	
92	    /** Once more than this many owners already carry a given day's registration date, a new owner
93	     * created for that day is flagged with {@code bulkSignupWarning} to signal a bulk-signup surge. */
94	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
95	
96	    /** HTTP header carrying the client-supplied idempotency key for a create. */
97	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
98	
99	    private final ClinicService clinicService;
100	
101	    private final OwnerMapper ownerMapper;
102	
103	    private final PetMapper petMapper;
104	
105	    private final VisitMapper visitMapper;
106	
107	    private final HttpServletRequest request;
108	
109	    private final IdempotencyStore idempotencyStore;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper,
115	                                 HttpServletRequest request,
116	                                 IdempotencyStore idempotencyStore) {
117	        this.clinicService = clinicService;
118	        this.ownerMapper = ownerMapper;
119	        this.petMapper = petMapper;
120	        this.visitMapper = visitMapper;
121	        this.request = request;
122	        this.idempotencyStore = idempotencyStore;
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
143	        Owner owner = this.clinicService.findOwnerById(ownerId);
144	        if (owner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        // Idempotent create: if this request carries an Idempotency-Key we have already created an
154	        // owner for, return that original owner with 200 OK instead of creating a duplicate.
155	        String idempotencyKey = request.getHeader(IDEMPOTENCY_KEY_HEADER);
156	        boolean hasIdempotencyKey = idempotencyKey != null && !idempotencyKey.isBlank();
157	        if (hasIdempotencyKey) {
158	            Optional<Owner> existing = this.idempotencyStore.find(idempotencyKey)
159	                .map(this.clinicService::findOwnerById);
160	            if (existing.isPresent()) {
161	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing.get()), HttpStatus.OK);
162	            }
163	        }
164	        HttpHeaders headers = new HttpHeaders();
165	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
166	        // The effective registration date (supplied, or the server date when omitted) must fall on
167	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
168	        // registration date — the stored value, the per-day limit below and the membership number —
169	        // uses this adjusted date.
170	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
171	        owner.setRegistrationDate(effectiveDate);
172	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
173	        // further creates for that day with 429 Too Many Requests.
174	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
175	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
176	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
177	        }
178	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
179	        // for its registration date, signalling a bulk-signup surge.
