3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	
7	/**
8	 * Validates that an owner supplies a postal address in EITHER form: a non-blank structured
9	 * {@code addressLine1}, or the flat {@code address}. This keeps the request contract
10	 * backward-compatible (earlier owners carrying only the flat {@code address} stay valid) while
11	 * also accepting owners that provide the structured address fields instead.
12	 */
13	public class AddressPresenceValidator implements ConstraintValidator<AddressPresenceValidation, OwnerFieldsDto> {
14	
15	    @Override
16	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
17	        if (owner == null) {
18	            return true;
19	        }
20	        return isPresent(owner.getAddressLine1()) || isPresent(owner.getAddress());
21	    }
22	
23	    private boolean isPresent(String value) {
24	        return value != null && !value.trim().isEmpty();
25	    }
26	}
